(function(root){
 const C=typeof module!=='undefined'&&module.exports?require('./account-catalog.js'):root.FamilyAccountCatalog;
 function distribution(balances,owner=null){const rows=balances.filter(a=>!owner||a.owner===owner),groups=new Map();let unknown=0;for(const a of rows){if(!Number.isSafeInteger(a.cents)){unknown++;continue;}const type=a.typeDetail||C.normalize(a.type)||'其他',sum=(groups.get(type)||0)+a.cents;if(!Number.isSafeInteger(sum))throw Error('资产合计超出计算范围。');groups.set(type,sum);}const parts=[...groups].map(([type,cents])=>({type,cents})).sort((a,b)=>(C.types.includes(a.type)?C.types.indexOf(a.type):C.types.length)-(C.types.includes(b.type)?C.types.indexOf(b.type):C.types.length));const total=parts.reduce((n,p)=>n+p.cents,0);if(!Number.isSafeInteger(total))throw Error('资产合计超出计算范围。');return{parts,total,unknown,count:rows.length,hasNegative:parts.some(p=>p.cents<0)};}
 if(typeof module!=='undefined'&&module.exports){module.exports={distribution};return;}
 const colors=['#8b64e8','#1999c4','#19a58b','#e4a136','#df5987','#6478d8','#bd7c4a','#84939d'];let owner=null;
 function panel(title,selector){const a=document.createElement('article');a.className='panel asset-distribution';a.innerHTML='<div class="panel-head"><div><h2></h2><p>按各账户最新已保存的余额／估值折合人民币，独立于收支日期筛选。</p></div></div><div class="asset-owner-tabs"></div><div class="asset-distribution-body"></div>';a.querySelector('h2').textContent=title;if(!selector)a.querySelector('.asset-owner-tabs').hidden=true;return a;}
 const assets=panel('资产类型分布 · 成员与家庭',true),overview=panel('家庭资产类型分布',false);$('unifiedAccounts').after(assets);$('trend').after(overview);
 const color=type=>{const index=C.types.indexOf(type);return colors[(index>=0?index:[...type].reduce((n,c)=>n+c.codePointAt(0),0))%colors.length];};
 const name=key=>key===null?'家庭合计':memberName(key);
 function paint(a,key){const box=a.querySelector('.asset-distribution-body');box.replaceChildren();const data=distribution(D.balances||[],key),note=document.createElement('p');note.className='muted full';note.textContent=name(key)+' · '+data.count+'个账户 · '+(data.unknown?'有'+data.unknown+'个账户金额未知，图中仅展示已知部分。':'合计 '+money(data.total))+' 按当前已保存人民币估值分类，未拆分银行存款与银行理财。';box.append(note);if(!data.count){box.append(document.createTextNode('尚无账户。'));return;}
 const grid=document.createElement('div');grid.className='asset-distribution-grid';const pie=document.createElement('div'),bars=document.createElement('div');const h1=document.createElement('h3'),h2=document.createElement('h3');h1.textContent='资产占比';h2.textContent='各类型资产金额';pie.append(h1);bars.append(h2);const tip=document.createElement('p');tip.className='composition-tip';tip.setAttribute('role','status');tip.textContent='点击图形或图例查看金额与占比';
 if(data.total>0&&!data.hasNegative){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.classList.add('income-donut');svg.setAttribute('viewBox','0 0 260 260');svg.setAttribute('role','img');svg.setAttribute('aria-label',name(key)+'资产类型占比');let offset=0;data.parts.forEach((p,i)=>{if(p.cents<=0)return;const share=p.cents/data.total,c=document.createElementNS(svg.namespaceURI,'circle'),text=p.type+'：'+money(p.cents)+' · '+(share*100).toFixed(1)+'%';for(const [k,v]of Object.entries({cx:130,cy:130,r:90,fill:'none',stroke:color(p.type),'stroke-width':30,pathLength:100,'stroke-dasharray':share*100+' '+(100-share*100),'stroke-dashoffset':-offset,transform:'rotate(-90 130 130)',tabindex:0,'aria-label':text}))c.setAttribute(k,v);c.onpointerenter=c.onfocus=c.onclick=()=>tip.textContent=text;svg.append(c);offset+=share*100;});const t=document.createElementNS(svg.namespaceURI,'text');for(const [k,v]of Object.entries({x:130,y:135,'text-anchor':'middle',fill:'currentColor','font-size':19}))t.setAttribute(k,v);t.textContent=money(data.total);svg.append(t);pie.append(svg);}else{const p=document.createElement('p');p.className='empty';p.textContent=data.hasNegative?'包含负余额，不能用饼图表达占比；柱高表示绝对值，负数以金额符号区分。':data.unknown?'暂无已知的正资产金额。':'资产合计为0，暂无占比。';pie.append(p);}
 const columns=document.createElement("div");columns.className="asset-type-columns";bars.append(columns);const max=data.parts.reduce((n,p)=>Math.max(n,Math.abs(p.cents)),1);for(const [i,p]of data.parts.entries()){const row=document.createElement('button');row.type='button';row.className='asset-type-bar';const label=document.createElement('span'),amount=document.createElement('strong'),track=document.createElement('span'),fill=document.createElement('i');label.textContent=p.type;amount.textContent=money(p.cents);track.className='asset-type-track';fill.style.width="100%";fill.style.height=Math.abs(p.cents)/max*100+'%';fill.style.background=color(p.type);track.append(fill);row.append(label,amount,track);row.onclick=row.onfocus=row.onpointerenter=()=>tip.textContent=p.type+'：'+money(p.cents)+(data.total>0&&!data.hasNegative?' · '+(p.cents/data.total*100).toFixed(1)+'%':'');columns.append(row);}grid.append(pie,bars);box.append(grid,tip);
 }
 function render(){if(!D.live)return;const tabs=assets.querySelector('.asset-owner-tabs');tabs.replaceChildren();const choices=[null,...(D.memberProfiles||[]).filter(p=>p.active).map(p=>p.key),'共同'];if(!choices.includes(owner))owner=null;for(const key of choices){const b=document.createElement('button');b.className='outline';b.type='button';b.textContent=name(key);b.setAttribute('aria-pressed',String(key===owner));b.classList.toggle('active',key===owner);b.onclick=()=>{owner=key;render();};tabs.append(b);}paint(assets,owner);paint(overview,null);}
 root.FamilyAssetDistribution={render};document.addEventListener('family-ledger-ready',render);document.addEventListener('family-session-ready',render);document.addEventListener('family-app-ready',render);if(D.live)render();
})(globalThis);
